// brandOf 先看类型，再按地址认域名——OpenRouter、Ollama 这类是以 custom 类型接进来的，
// 只看 kind 会全部落成一个灰色的 API 方块。
export function brandOf(p){
  const k=p?.kind||'';
  if(brands[k])return k;
  const u=(p?.base_url||'').toLowerCase();
  if(!u)return '';
  for(const[m,name]of[['openrouter.ai','openrouter'],['deepseek.com','deepseek'],['z.ai','zai'],['bigmodel.cn','zai'],['commandcode.ai','commandcode'],['opencode.ai','opencode'],['api.openai.com','openai'],['anthropic.com','anthropic'],['ollama','ollama'],['11434','ollama']])if(u.includes(m))return name;
  return '';
}

// 这几家有官方 app icon（自带品牌底色），直接用图；
// 其余用单色路径，形状同样取自官方 logo。
const brandImages=new Set(['anthropic','commandcode','deepseek','openrouter','zai','opencode']);

export function brand(name){
  if(brandImages.has(name))return `<img class="provider-logo image" src="assets/brands/${name}.png" alt="" aria-hidden="true">`;
  return `<svg class="provider-logo" width="20" height="20" viewBox="0 0 24 24" fill="currentColor" fill-rule="evenodd" aria-hidden="true">${brands[name]||''}</svg>`;

}

export function icon(name,cls=''){
  return `<svg class="icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.grid}</svg>`;

}
